  const h=make();h.app.importDocument(doc);assert.equal(h.app.renderVals().comparing,true);assert.equal(h.app.shownColor(h.app.state.items.find(i=>i.id==='x')),'#805400');h.app.toggleCmpMarks();assert.equal(h.app.shownColor(h.app.state.items.find(i=>i.id==='x')),h.app.state.items.find(i=>i.id==='x').color);assert.equal(h.app.renderVals().marksLabel,'비교 표시 보이기');assert.equal(h.app.reviewList().length,r.changes.filter(c=>c.scope==='item').length,'the review list does not depend on the marks');
