test('Sequential palette tones follow schedule order, reverse and undo in one operation',()=>{for(const direction of [1,-1]){const a=group35Fixture(),before=a.snapshot(),peer=JSON.stringify(a.state.items[5]),base='#8b5cf6';a.onSequenceColor({currentTarget:{dataset:{color:base,direction:String(direction)}}});const tones=direction>0?[-.55,-.3,0,.3,.55]:[.55,.3,0,-.3,-.55];for(let n=0;n<5;n++)assert.equal(a.state.items[n].color,a.paletteTone(base,tones[n]));assert.equal(JSON.stringify(a.state.items[5]),peer);assert.equal(a.state.hist.length,1);a.undo();assert.equal(a.snapshot(),before);a.state.readOnly=true;a.onSequenceColor({currentTarget:{dataset:{color:base,direction:'1'}}});assert.equal(a.snapshot(),before);}});
test('Group vertical keyboard adjustment moves every selected item without editing peers or dates',()=>{const a=group35Fixture(),before=JSON.parse(a.snapshot());a.onKey({key:'ArrowDown',shiftKey:true,target:{tagName:'DIV'},preventDefault(){}});for(let n=0;n<5;n++){assert.equal(a.state.items[n].trackY,before.items[n].trackY+10);assert.equal(a.state.items[n].s,before.items[n].s);assert.equal(a.state.items[n].e,before.items[n].e);}assert.equal(JSON.stringify(a.state.items[5]),JSON.stringify(before.items[5]));assert.equal(a.state.joinPrompt,undefined);a.undo();assert.equal(a.snapshot(),JSON.stringify(before));});
test('Horizontal keyboard movement asks before joining; cancel retains movement and gaps',()=>{const a=group35Fixture(),before=JSON.parse(a.snapshot());a.onKey({key:'ArrowRight',target:{tagName:'DIV'},preventDefault(){}});assert.equal(a.state.joinPrompt.length,5);for(let n=0;n<5;n++){assert.equal(a.state.items[n].s,a.shiftDay(before.items[n].s,1));assert.equal(a.state.items[n].e,a.shiftDay(before.items[n].e,1));assert.equal(a.state.items[n].trackY,before.items[n].trackY);}assert.equal(JSON.stringify(a.state.items[5]),JSON.stringify(before.items[5]));const moved=a.snapshot();a.joinKey({key:'Escape',preventDefault(){},stopPropagation(){}});assert.equal(a.state.joinPrompt,null);assert.equal(a.snapshot(),moved);a.undo();assert.equal(a.snapshot(),JSON.stringify(before));});
test('Joining preserves calendar durations across unequal months and leaves peers fixed',()=>{const a=group35Fixture();a.state.items[0].s=.8;a.state.items[0].e=1.2;const duration=i=>(Date.parse(a.isoOf(i.e))-Date.parse(a.isoOf(i.s)))/86400000;const days=a.state.items.slice(0,5).map(duration),before=a.snapshot(),peer=JSON.stringify(a.state.items[5]);a.askJoin();a.applyJoin();assert.equal(a.state.joinPrompt,null);for(let n=1;n<5;n++){assert.equal(a.state.items[n].s,a.state.items[n-1].e);assert.equal(duration(a.state.items[n]),Math.round(days[n]));}assert.equal(JSON.stringify(a.state.items[5]),peer);assert.equal(a.state.hist.length,1);a.undo();assert.equal(a.snapshot(),before);});
test('Group height step applies each half-unit from its own value and does not resize peers',()=>{const a=group35Fixture(),unit=a.heightUnit();a.state.items[0].trackH=unit*.41;a.state.items[1].trackH=unit*.85;const before=a.snapshot(),peer=JSON.stringify(a.state.items[5]);a.stepSelectedHeights(1);assert.equal(a.state.items[0].trackH,unit*.5);assert.equal(a.state.items[1].trackH,unit);for(let n=2;n<5;n++)assert.equal(a.state.items[n].trackH,unit);assert.equal(JSON.stringify(a.state.items[5]),peer);a.undo();assert.equal(a.snapshot(),before);});
test('Group height handle resizes all selected items without treating them as obstacles',()=>{const a=group35Fixture(),before=JSON.parse(a.snapshot()),peer=JSON.stringify(a.state.items[5]);a.onItemDown({button:0,clientX:0,clientY:0,currentTarget:{dataset:{id:'tone-2',mode:'bottom'}},target:{tagName:'DIV'},stopPropagation(){}});assert.equal(a.drag.heightGroup.length,5);a.onMove({clientX:0,clientY:15});a.stopDrag();for(let n=0;n<5;n++)assert.equal(a.state.items[n].trackH,before.items[n].trackH+15);assert.equal(JSON.stringify(a.state.items[5]),peer);assert.equal(a.state.joinPrompt,undefined);a.undo();assert.equal(a.snapshot(),JSON.stringify(before));});
test('Horizontal pointer group asks only after release; vertical movement never asks',()=>{for(const horizontal of [false,true]){const a=group35Fixture(),before=a.snapshot();a.onItemDown({button:0,clientX:0,clientY:0,currentTarget:{dataset:{id:'tone-2'}},target:{tagName:'DIV'},stopPropagation(){}});a.onMove({clientX:horizontal?20:0,clientY:horizontal?0:15});assert.equal(a.state.joinPrompt,undefined);a.stopDrag();assert.equal(!!a.state.joinPrompt,horizontal);if(horizontal)a.cancelJoin();a.undo();assert.equal(a.snapshot(),before);}});

test('Command D duplicates against each right edge with identical presentation and fixed originals',()=>{for(const count of [1,3]){const a=group35Fixture();a.state.items.slice(0,count).forEach((it,n)=>Object.assign(it,{label:'Copy '+n,memo:'Keep memo',variant:'tint',labelSize:17,labelBold:true,labelStrike:true,labelAlign:'right',stackOrder:11+n,hideDate:true}));a.selectItems(a.state.items.slice(0,count).map(i=>i.id));const before=a.snapshot(),originals=JSON.parse(before).items;a.onKey({key:'d',code:'KeyD',metaKey:true,target:{tagName:'DIV'},preventDefault(){}});const copies=a.state.items.slice(originals.length);assert.equal(copies.length,count);for(let n=0;n<count;n++){const old=originals[n],next=copies[n];assert.equal(next.s,old.e);assert.ok(Math.abs((next.e-next.s)-(old.e-old.s))<1e-10);for(const key of Object.keys(old).filter(k=>!['id','s','e'].includes(k)))assert.deepEqual(next[key],old[key],key);assert.notEqual(next.id,old.id);}assert.deepEqual(JSON.parse(JSON.stringify(a.state.items.slice(0,originals.length))),originals);assert.equal(a.state.hist.length,1);a.undo();assert.equal(a.snapshot(),before);}});
test('Floating duplicate attaches at its pixel right edge without vertical offset',()=>{const a=make().app;for(const kind of ['sticky','image']){const it={id:'float-'+kind,kind,row:'',lane:0,span:1,s:1,e:1,y:73,w:211,h:93,color:'#fdf3d0',label:'same',memo:'same',src:kind==='image'?'data:image/png;base64,AA==':undefined};a.state.items=[it];a.selectItems([it.id]);a.duplicateSel();const copy=a.selItem();assert.ok(Math.abs(a.xOf(copy.s)-a.xOf(it.s)-it.w)<1e-8);for(const key of ['y','w','h','color','label','memo','src'])assert.equal(copy[key],it[key]);}});
test('Gradient buttons express palette lightness in both directions and retain sequential colors',()=>{const a=group35Fixture(),g=a.toneGradients('#8b5cf6'),dark=a.paletteTone('#8b5cf6',-.55),light=a.paletteTone('#8b5cf6',.55);assert.equal(g.lightToDark,`linear-gradient(to right,${light},#8b5cf6,${dark})`);assert.equal(g.darkToLight,`linear-gradient(to right,${dark},#8b5cf6,${light})`);a.onSequenceColor({currentTarget:{dataset:{color:'#8b5cf6',direction:'-1'}}});assert.equal(a.state.items[0].color,light);assert.equal(a.state.items[4].color,dark);});

test('Selected endpoint arrows change only that edge by one calendar day, including Shift',()=>{for(const field of ['s','e']){const a=group35Fixture();a.selectItems(['tone-2']);const old={...a.selItem()},peer=JSON.stringify(a.state.items[5]);a.state.edgeSelection={id:old.id,field};a.onKey({key:'ArrowRight',shiftKey:true,target:{tagName:'DIV'},preventDefault(){}});const next=a.selItem();assert.equal(next[field],a.shiftDay(old[field],1));assert.equal(next[field==='s'?'e':'s'],old[field==='s'?'e':'s']);assert.equal(next.trackY,old.trackY);assert.equal(JSON.stringify(a.state.items[5]),peer);assert.equal(a.state.joinPrompt,undefined);}});
test('Multi-selection date step changes each selected end, keeps starts and asks to join',()=>{const a=group35Fixture(),before=JSON.parse(a.snapshot());a.onStep({currentTarget:{dataset:{field:'e',delta:'1'}}});for(let n=0;n<5;n++){assert.equal(a.state.items[n].e,a.shiftDay(before.items[n].e,1));assert.equal(a.state.items[n].s,before.items[n].s);}assert.equal(a.state.joinPrompt.length,5);a.cancelJoin();a.undo();assert.equal(a.snapshot(),JSON.stringify(before));});
test('Multi-selection calendar input applies equal calendar-day delta to each selected start',()=>{const a=group35Fixture(),before=JSON.parse(a.snapshot()),selected=a.selItem(),date=a.isoOf(a.shiftDay(selected.s,-2));a.onDateField({currentTarget:{dataset:{field:'s'},value:date}});for(let n=0;n<5;n++){assert.equal(a.state.items[n].s,a.shiftDay(before.items[n].s,-2));assert.equal(a.state.items[n].e,before.items[n].e);}assert.equal(a.state.joinPrompt.length,5);});
test('Multi-selection pointer end resize updates all ends and prompts only upon release',()=>{const a=group35Fixture(),before=JSON.parse(a.snapshot());a.state.cfg.magnet=true;a.onItemDown({button:0,clientX:0,clientY:0,currentTarget:{dataset:{id:'tone-2',mode:'r'}},target:{tagName:'DIV'},stopPropagation(){}});a.onMove({clientX:20,clientY:0});assert.equal(a.state.joinPrompt,undefined);a.stopDrag();for(let n=0;n<5;n++){assert.ok(a.state.items[n].e>before.items[n].e);assert.equal(a.state.items[n].s,before.items[n].s);assert.equal(a.state.items[n].e,a.snapDateEdge(a.state.items[n].e));}assert.equal(a.state.joinPrompt.length,5);});
test('Overlap toggle trims only colliding dates and restores preview from original at each frame',()=>{const {h,it}=heightFixture(),a=h.app;a.state.cfg.magnet=false;a.state.cfg.shrinkOthers=true;Object.assign(it,{s:2,e:3,trackY:44,trackH:44});a.state.items=[it,{...it,id:'peer',s:0,e:2.5},{...it,id:'below',s:0,e:2.5,trackY:200}];a.renderVals();const baseline=a.snapshot(),below=JSON.stringify(a.state.items[2]);a.onItemDown({button:0,clientX:0,clientY:0,currentTarget:{dataset:{id:it.id}},target:{tagName:'DIV'},stopPropagation(){}});a.onMove({clientX:-20,clientY:0});assert.ok(a.state.items[1].e<2.5);assert.equal(a.state.items[1].trackY,44);assert.equal(a.state.items[1].trackH,44);a.onMove({clientX:a.xOf(4)-a.xOf(2),clientY:0});assert.equal(a.state.items[1].e,2.5);assert.equal(JSON.stringify(a.state.items[2]),below);a.stopDrag();a.undo();assert.equal(a.snapshot(),baseline);});
test('Milestone header ignores old lane gaps and uses the minimum non-overlapping rows',()=>{const a=make().app;const marker=(id,s)=>({id,kind:'marker',row:'',lane:0,span:1,s,e:s,label:'M',color:'#66707a',markerLane:6});a.state.cfg.showNow=false;a.state.items=[marker('m1',1),marker('m2',4),marker('m3',7)];let v=a.renderVals();assert.equal(a._markerRows,1);assert.ok(v.markersView.every(m=>m.top==='0px'));a.state.items[1].s=1;a.state.items[1].e=1;v=a.renderVals();assert.equal(a._markerRows,2);a.state.items[2].s=1;a.state.items[2].e=1;a.renderVals();assert.equal(a._markerRows,3);a.state.items[1].s=4;a.state.items[2].s=7;a.renderVals();assert.equal(a._markerRows,1);});

test('Enabling overlap trimming immediately applies to selection and undo restores toggle and dates',()=>{const {h,it}=heightFixture(),a=h.app;Object.assign(it,{s:2,e:3,trackY:44,trackH:44});a.state.items=[it,{...it,id:'peer',s:0,e:2.5}];a.state.cfg.shrinkOthers=false;a.selectItems([it.id]);const before=a.snapshot();a.setOverlap();assert.equal(a.state.cfg.shrinkOthers,true);assert.equal(a.state.items[1].e,2);assert.equal(a.state.items[1].trackY,44);assert.equal(a.state.items[1].trackH,44);a.undo();assert.equal(a.snapshot(),before);});

test('Multi-selection palette applies one color once and undo preserves all items',()=>{const h=make(),ids=h.app.state.items.slice(0,3).map(i=>i.id),before=h.app.snapshot();h.app.selectItems(ids);h.app.onColor({currentTarget:{dataset:{color:'#17a2a2'}}});for(const id of ids)assert.equal(h.app.state.items.find(i=>i.id===id).color,'#17a2a2');assert.equal(h.app.state.items[3].color,JSON.parse(before).items[3].color);h.app.undo();assert.equal(h.app.snapshot(),before);});
test('Connected memo editor shares the badge coordinates and marker keeps an editable minimum',()=>{const h=make(),it=h.app.state.items.find(i=>i.kind==='flag');it.labelDx=80;it.labelDy=50;const before=h.app.renderVals().rowsView.flatMap(r=>r.flags).find(f=>f.id===it.id);h.app.onItemDbl({stopPropagation(){},currentTarget:{dataset:{id:it.id}}});const after=h.app.renderVals().rowsView.flatMap(r=>r.flags).find(f=>f.id===it.id);for(const field of ['left','top','labelLeft','labelTop'])assert.equal(after[field],before[field]);assert.ok(parseFloat(after.editWidth)>=72);assert.match(html,/left:\{\{ f.labelLeft \}\};top:\{\{ f.labelTop \}\};width:\{\{ f.editWidth \}\}/);assert.match(html,/input.focus\(\{preventScroll:true\}\)/);const marker=h.app.state.items.find(i=>i.kind==='marker');marker.label='';h.app.state.editing=marker.id;assert.equal(h.app.renderVals().markersView.find(i=>i.id===marker.id).editMinW,'120px');});

test('Narrow-screen memo double-click cancels the pending panel and keeps the editor visible',()=>{const h=make(),it=h.app.state.items.find(i=>i.kind==='flag'),before=h.app.snapshot();h.app.narrowScreen=()=>true;h.app.state.panel=false;const e={button:0,clientX:0,clientY:0,target:{tagName:'DIV'},currentTarget:{dataset:{id:it.id}},stopPropagation(){},preventDefault(){}};h.app.onItemDown(e);h.app.stopDrag();h.app.onItemDbl(e);h.flush();assert.equal(h.app.state.editing,it.id);assert.equal(h.app.state.panel,false);assert.equal(h.app.snapshot(),before);});

test('Calendar date conversion uses the real component method and generated bundle has no retired call',()=>{const h=make(),ui=fs.readFileSync('mapstone-ui.js','utf8'),bundled=fs.readFileSync('index.html','utf8'),zlib=require('node:zlib');assert.equal(typeof h.app.monthOfISO,'function');assert.equal(h.app.monthOfISO(h.app.isoOf(1.5)),1.5);assert.doesNotMatch(ui,/app\.mOfISO\(/);const manifest=JSON.parse(bundled.match(/<script type="__bundler\/manifest">([\s\S]*?)<\/script>/)[1]);const adapter=Object.values(manifest).filter(r=>r.mime.includes('javascript')).map(r=>zlib.gunzipSync(Buffer.from(r.data,'base64')).toString()).find(s=>s.includes('function openCalendar'));assert.ok(adapter);assert.doesNotMatch(adapter,/app\.mOfISO\(/);assert.match(adapter,/app\.monthOfISO\(selected\)/);});

test('Item inner stroke darkens normal colors and lightens very dark fills without changing geometry',()=>{const a=make().app;for(const color of ['#66707a','#dbe9fa','#111827']){const it={color,variant:'solid'};const stroke=a.itemStroke(it);assert.notEqual(stroke,color);assert.equal(a.lum(stroke)>a.lum(color),a.lum(color)<.12);}assert.ok(a.lum(a.itemStroke({color:'#111827',variant:'tint'}))<a.lum('#111827'));});
test('Milestone preferred vertical lane displaces overlapping peers and collapses when separated',()=>{const a=make().app;a.state.cfg.showNow=false;const m=(id)=>({id,kind:'marker',row:'',lane:0,span:1,s:2,e:2,label:'M',color:'#66707a'});a.state.items=[m('a'),m('b')];a.renderVals();a.selectItems(['b']);a.shiftSelectedVertically(-1);a.renderVals();assert.equal(a._markerSlots.b,0);assert.equal(a._markerSlots.a,1);assert.equal(a._markerRows,2);a.state.items[1].s=6;a.state.items[1].e=6;a.renderVals();assert.equal(a._markerRows,1);assert.equal(a._markerSlots.b,0);assert.doesNotThrow(()=>C.validate(a.dataDocument()));});
